// מה רצוי: «לפי Figma S-17 (450:3687) הכותרת בראש מסך התפילה ממורכזת … גם במסך ברכה הכותרת והנוסח ממורכזים כמו במסכי התפילה.»
// F-96 AC1: в шапке название и нусах. Факт 21.10: кнопка-заголовок брахи — центр 201 pt (= центр экрана 402/2), как у «שחרית»;
// группа текст+«˅» ≈196 pt (2110-414ae351-etz.png, -shacharit.png). Допуск ±4 pt (как KB-414ae351 19.10: было 223 vs 201).
// После #4cfbf19e список брахот под другой вкладкой — openBrachotList пробует обе. Кейс: .qa/tests/guided-prayer/GP-11-bracha-title-centered.md.
import { expect } from '@wdio/globals';
import { skipWith } from '../_lib/app-0710.ts';
import { goHome, openCatalogPrayer, labelOf } from '../_lib/readiness-1910.ts';
import { openBracha, titleButton, box, centerX, screenCenterX } from '../_lib/app-2110.ts';

const TOL = 4;

async function titleCenterDelta(where: string) {
  const el = await titleButton();
  const b = await box(el);
  const d = centerX(b) - (await screenCenterX());
  console.log(`[GP-11] ${where}: «${await labelOf(el)}» центр ${centerX(b).toFixed(1)}, экран ${(await screenCenterX()).toFixed(1)}, Δ=${d.toFixed(1)}`);
  return { d, label: await labelOf(el) };
}

describe('21.10 — заголовок экрана брахи по центру (#1c8de4)', () => {
  afterEach(async () => { await goHome().catch(() => {}); });

  for (const title of ['בורא פרי העץ', 'ברכה אחרונה מעין שלוש', 'שהכל נהיה בדברו']) {
    it(`GP-11 Браха «${title}»: заголовок «<ברכה> (<נוסח>)» по центру экрана (±${TOL} pt), в нём название и нусах #1c8de4 #414ae351 F-96 AC1 @prod-safe`, async function () {
      // 21.10 проверена «בורא פרי העץ»; остальные — клетки Т1.2/Т1.3 брифа (длинная / короткая), названия из списка брахот 19.10.
      try { await openBracha(title); } catch (e) {
        if (title === 'בורא פרי העץ') throw e;
        skipWith(this, `нет брахи «${title}» в списке — поправить название по списку`);
      }
      const { d, label } = await titleCenterDelta(title);
      expect(label).toMatch(/אשכנזי|ספרדי/);              // нусах в шапке (iOS: «בחירת נוסח. הנוסח המוצג: X»)
      expect(Math.abs(d)).toBeLessThanOrEqual(TOL);
    });
  }

  it(`GP-11 Регресс #b398d352: заголовок «שחרית (<נוסח>)» по-прежнему по центру (±${TOL} pt) #1c8de4 #b398d352 @prod-safe`, async () => {
    await openCatalogPrayer('שחרית');
    const { d } = await titleCenterDelta('שחרית');
    expect(Math.abs(d)).toBeLessThanOrEqual(TOL);
  });
});
